#nullable enable
using System;using System.IO;using System.Linq;using System.Threading;using OneStarMaker.Runtime.BuildContent.Distribution;using UnityEditor;using UnityEngine;
namespace SampleGame.DependOnAll.Editor.Build
{
    internal sealed class ContentDeliveryWindow:EditorWindow
    {
        private const string SettingsPath="UserSettings/OSMContentDelivery.json";private Settings _settings=new();private CancellationTokenSource? _cts;private string _status="";
        [MenuItem("Tools/OSM/Content/Delivery")]private static void Open()=>GetWindow<ContentDeliveryWindow>("OSM Content Delivery");
        private void OnEnable(){if(File.Exists(SettingsPath))_settings=JsonUtility.FromJson<Settings>(File.ReadAllText(SettingsPath))??new Settings();}
        private void OnDisable(){_cts?.Cancel();_cts?.Dispose();}
        private void OnGUI(){_settings.sourceMode=EditorGUILayout.Popup("Source",_settings.sourceMode,new[]{"Local/LAN directory","HTTP base URL","Installed offline"});if(_settings.sourceMode==0)_settings.sourceRoot=EditorGUILayout.TextField("Published directory",_settings.sourceRoot);else if(_settings.sourceMode==1)_settings.httpBase=EditorGUILayout.TextField("HTTP base URL",_settings.httpBase);else _settings.installedRoot=EditorGUILayout.TextField("Installed revision root",_settings.installedRoot);_settings.digest=EditorGUILayout.TextField("Manifest SHA-256",_settings.digest);_settings.contentSet=EditorGUILayout.TextField("Content set",_settings.contentSet);_settings.revision=EditorGUILayout.TextField("Revision",_settings.revision);_settings.cacheRoot=EditorGUILayout.TextField("Cache root",_settings.cacheRoot);_settings.representation=EditorGUILayout.TextField("Representation",_settings.representation);_settings.budget=EditorGUILayout.LongField("Disk budget",_settings.budget);
          using(new EditorGUI.DisabledScope(EditorApplication.isPlayingOrWillChangePlaymode)){if(GUILayout.Button("Prepare"))_ = Prepare();if(GUILayout.Button("Use For Next Play"))ContentDeliveryPlayBridge.Apply(_settings.installedRoot,_settings.digest,_settings.revision,_settings.contentSet,_settings.representation);if(GUILayout.Button("Reset"))ContentDeliveryPlayBridge.Reset();}EditorGUILayout.HelpBox(_status,MessageType.Info);}
        private async System.Threading.Tasks.Task Prepare(){_cts?.Cancel();_cts?.Dispose();_cts=new CancellationTokenSource();try{Save();var store=new ContentCacheStore(_settings.cacheRoot);if(_settings.sourceMode==2){var entry=store.Inspect().Entries.FirstOrDefault(x=>x.RevisionRoot==Path.GetFullPath(_settings.installedRoot)&&x.ManifestSha256==_settings.digest&&x.ContentSet==_settings.contentSet&&x.Revision==_settings.revision)??throw new InvalidOperationException("Installed revision does not match the requested identity and digest.");_status="Selected installed revision: "+entry.RevisionRoot;}else{using IContentArtifactSource source=_settings.sourceMode==1?new HttpContentArtifactSource(new Uri(_settings.httpBase)):new LocalContentArtifactSource(_settings.sourceRoot);var request=new ContentInstallRequest(_settings.digest,_settings.contentSet,_settings.revision,"StandaloneWindows64-Player",Application.unityVersion,2,_settings.budget);var result=await new ContentInstaller(store).InstallAsync(request,source,_cts.Token);_settings.installedRoot=result.RevisionRoot;_status="Prepared: "+result.RevisionRoot;}Save();}catch(Exception ex){_status=ex.Message;}Repaint();}
        private void Save(){Directory.CreateDirectory(Path.GetDirectoryName(SettingsPath)!);File.WriteAllText(SettingsPath,JsonUtility.ToJson(_settings,true));}
        [Serializable]private sealed class Settings{public int sourceMode;public string sourceRoot="";public string httpBase="";public string digest="";public string contentSet="bs4-spring-full";public string revision="";public string cacheRoot="";public string representation="Full";public long budget=10L*1024*1024*1024;public string installedRoot="";}
    }
}
